static int64_t pi_limit_32(uint32_t N) {
    if (N < 2) return 0;
    if (N == 2) return 1;
    if (N == 3) return 2;
    if (N == 4) return 2;
    if (N == 5) return 3;

    uint32_t v = (uint32_t)sqrt((double)N);
    while ((uint64_t)(v + 1) * (v + 1) <= N) v++;
    while ((uint64_t)v * v > N) v--;

    uint32_t smalls_buf[65537];
    int32_t larges_buf[32769];
    uint8_t skip_buf[65537];
    uint32_t roughs_buf[32769];

    uint32_t *smalls = smalls_buf;
    int32_t *larges = larges_buf;
    uint8_t *skip = skip_buf;
    uint32_t *roughs = roughs_buf;

    memset(skip, 0, (v + 1) * sizeof(uint8_t));

    for (uint32_t i = 1; i <= v; i++) {
        smalls[i] = (i - 1) >> 1;
    }
    uint32_t s = (v + 1) >> 1;
    for (uint32_t i = 0; i < s; i++) {
        uint32_t d = 2 * i + 1;
        larges[i] = (int32_t)(((N / d) - 1) >> 1);
        roughs[i] = d;
    }

    int32_t p_cnt = 0;
    for (uint32_t p = 3; p <= v; p += 2) {
        if (!skip[p]) {
            uint32_t q = p * p;
            if ((uint64_t)q * q > N) break;
            skip[p] = 1;
            for (uint32_t i = q; i <= v; i += 2 * p) skip[i] = 1;
            uint32_t ns = 0;
            for (uint32_t k = 0; k < s; k++) {
                uint32_t i = roughs[k];
                if (skip[i]) continue;
                uint32_t d = i * p;
                larges[ns] = larges[k] - (d <= v ? larges[smalls[d] - p_cnt] : (int32_t)smalls[N / d]) + p_cnt;
                roughs[ns++] = i;
            }
            s = ns;
            for (uint32_t i = v, j = (v / p - 1) | 1; j >= p; j -= 2) {
                uint32_t c = smalls[j] - p_cnt;
                for (uint32_t e = j * p; i >= e; i--) smalls[i] -= c;
            }
            p_cnt++;
        }
    }

    int64_t ans0 = larges[0] + (int64_t)(s + 2 * (p_cnt - 1)) * (int32_t)(s - 1) / 2;
    for (uint32_t k = 1; k < s; k++) ans0 -= larges[k];
    for (uint32_t l = 1; l < s; l++) {
        uint32_t q = roughs[l];
        uint32_t M = N / q;
        int32_t e = (int32_t)smalls[M / q] - p_cnt;
        if (e <= (int32_t)l) break;
        int64_t t = 0;
        for (int32_t k = (int32_t)l + 1; k <= e; k++) {
            t += smalls[M / roughs[k]];
        }
        ans0 += t - (int64_t)(e - (int32_t)l) * (p_cnt + (int32_t)l - 1);
    }

    return ans0 + 1;
}

int64_t pi_limit(int64_t N) {
    if (N < 2) return 0;
    if (N <= 0xFFFFFFFFLL) {
        return pi_limit_32((uint32_t)N);
    }

    int64_t v = (int64_t)sqrt((double)N);
    while ((v + 1) * (v + 1) <= N) v++;
    while (v * v > N) v--;

    int64_t *smalls = (int64_t *)malloc((v + 1) * sizeof(int64_t));
    int64_t *larges = (int64_t *)malloc((v + 1) * sizeof(int64_t));
    uint8_t *skip = (uint8_t *)calloc(v + 1, sizeof(uint8_t));
    int64_t *roughs = (int64_t *)malloc((v + 1) * sizeof(int64_t));

    for (int64_t i = 1; i <= v; i++) {
        smalls[i] = (i - 1) / 2;
    }
    int64_t s = (v + 1) / 2;
    for (int64_t i = 0; i < s; i++) {
        int64_t d = 2 * i + 1;
        larges[i] = (N / d - 1) / 2;
        roughs[i] = d;
    }

    int64_t p_cnt = 0;
    for (int64_t p = 3; p <= v; p += 2) {
        if (!skip[p]) {
            int64_t q = p * p;
            if (q * q > N) break;
            skip[p] = 1;
            for (int64_t i = q; i <= v; i += 2 * p) skip[i] = 1;
            int64_t ns = 0;
            for (int64_t k = 0; k < s; k++) {
                int64_t i = roughs[k];
                if (skip[i]) continue;
                int64_t d = i * p;
                larges[ns] = larges[k] - (d <= v ? larges[smalls[d] - p_cnt] : smalls[N / d]) + p_cnt;
                roughs[ns++] = i;
            }
            s = ns;
            for (int64_t i = v, j = (v / p - 1) | 1; j >= p; j -= 2) {
                int64_t c = smalls[j] - p_cnt;
                for (int64_t e = j * p; i >= e; i--) smalls[i] -= c;
            }
            p_cnt++;
        }
    }

    larges[0] += (s + 2 * (p_cnt - 1)) * (s - 1) / 2;
    for (int64_t k = 1; k < s; k++) larges[0] -= larges[k];
    for (int64_t l = 1; l < s; l++) {
        int64_t q = roughs[l];
        int64_t M = N / q;
        int64_t e = smalls[M / q] - p_cnt;
        if (e < l + 1) break;
        int64_t t = 0;
        for (int64_t k = l + 1; k <= e; k++) {
            t += smalls[M / roughs[k]];
        }
        larges[0] += t - (e - l) * (p_cnt + l - 1);
    }

    int64_t ans = larges[0] + 1;
    free(smalls);
    free(larges);
    free(skip);
    free(roughs);
    return ans;
}

int64_t count_primes(int64_t n) {
    if (n <= 2) return 0;
    return pi_limit(n - 1);
}

